import { Component } from '@angular/core';
import { CoursesService } from './services/courses.service';
import { Author } from './models/author.model';
import { Course } from './models/course.model';
import { Observable } from 'rxjs';
import { AuthService } from './auth/services/auth.service';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent {
  title = 'courses-app';
  courses: Course[] = [];
  authors: Author[] = [];

  isAuthorized$: Observable<boolean>;
  username: string = '';

  constructor(
    private coursesService: CoursesService,
    private authService: AuthService,
  ) {
    this.isAuthorized$ = this.authService.isAuthorized$;
  }

  ngOnInit() {
    this.coursesService.getAll().subscribe(courses => {
      this.courses = courses;
    });

    this.coursesService.getAllAuthors().subscribe(authors => {
      this.authors = authors;
    });

    this.authService.isAuthorized$.subscribe(isAuth => {
      if (isAuth) {
        this.username = 'ADMIN';
      } else {
        this.username = '';
      }
    });
  }

  onShowCourse(title: string) {
    console.log('Show course clicked:', title);
  }

  onEditCourse(title: string) {
    console.log('Edit course clicked:', title);
  }

  onDeleteCourse(title: string) {
    console.log('Delete course clicked:', title);
  }

  logout() {
    this.authService.logout();
  }
}
